// Git's documented exit statuses for git-config.
const (
	exitNotFound      = 1   // the key was not found
	exitInvalidKey    = 1   // the section or key is invalid
	exitUnsetMissing  = 5   // unset of a key that does not exist
	exitCannotReplace = 5   // single value cannot replace several
	exitFatal         = 128 // the config file could not be read
	exitUsage         = 129 // the command invocation is malformed
)

// configOpts holds the flags shared by `config`, `config get`, `config set`
// and `config unset`. Each command owns its own instance so the modern and
// legacy spellings stay independently parseable.
type configOpts struct {
	file   string
	local  bool
	global bool
	system bool

	all  bool
	path bool
}

var (
	legacyOpts configOpts
	getOpts    configOpts
	setOpts    configOpts
	unsetOpts  configOpts

	legacyGet        bool
	legacyGetAll     bool
	legacyAdd        bool
	legacyUnset      bool
	legacyUnsetAll   bool
	legacyReplaceAll bool
)

// registerLocation adds the flags that choose which configuration file to act
// on. They are mutually exclusive.
func (o *configOpts) registerLocation(cmd *cobra.Command) {
	cmd.Flags().StringVarP(&o.file, "file", "f", "", "Use the given config file instead of the repository config")
	cmd.Flags().BoolVar(&o.local, "local", false, "Use the repository config file")
	cmd.Flags().BoolVar(&o.global, "global", false, "Use the global (per-user) config file")
	cmd.Flags().BoolVar(&o.system, "system", false, "Use the system-wide config file")
	cmd.MarkFlagsMutuallyExclusive("file", "local", "global", "system")
}

func init() {
	for _, cmd := range []*cobra.Command{configCmd, configGetCmd, configSetCmd, configUnsetCmd} {
		cmd.SetFlagErrorFunc(func(_ *cobra.Command, err error) error {
			return usageError(err.Error())
		})
	}

	legacyOpts.registerLocation(configCmd)
	configCmd.Flags().BoolVar(&legacyOpts.path, "path", false,
		"Canonicalize the value as a path, expanding a leading ~")
	configCmd.Flags().BoolVar(&legacyGet, "get", false, "Get the value for the given key")
	configCmd.Flags().BoolVar(&legacyGetAll, "get-all", false, "Get all values for the given key")
	configCmd.Flags().BoolVar(&legacyAdd, "add", false, "Add a new value without altering existing ones")
	configCmd.Flags().BoolVar(&legacyUnset, "unset", false, "Remove the value for the given key")
	configCmd.Flags().BoolVar(&legacyUnsetAll, "unset-all", false, "Remove all occurrences of the key")
	configCmd.Flags().BoolVar(&legacyReplaceAll, "replace-all", false, "Replace all values for the given key")
	configCmd.MarkFlagsMutuallyExclusive("get", "get-all", "add", "unset", "unset-all", "replace-all")

	getOpts.registerLocation(configGetCmd)
	configGetCmd.Flags().BoolVar(&getOpts.all, "all", false, "Show all values for the key")
	configGetCmd.Flags().BoolVar(&getOpts.path, "path", false,
		"Canonicalize the value as a path, expanding a leading ~")

	setOpts.registerLocation(configSetCmd)
	configSetCmd.Flags().BoolVar(&setOpts.all, "all", false, "Replace all values for the key")

	unsetOpts.registerLocation(configUnsetCmd)
	configUnsetCmd.Flags().BoolVar(&unsetOpts.all, "all", false, "Remove all values for the key")

	configCmd.AddCommand(configGetCmd, configSetCmd, configUnsetCmd)
	rootCmd.AddCommand(configCmd)
}

var configCmd = &cobra.Command{
	Use:   "config [<options>] <key> [<value>]",
	Short: "Get or set repository configuration",
	Long: "Get or set configuration values.\n\n" +
		"The modern forms are `config get <key>`, `config set <key> <value>` and\n" +
		"`config unset <key>`. The legacy flag spellings (--get, --add, --unset-all\n" +
		"and a bare `config <key> [<value>]`) are also accepted.",
	Args:                  configArgs(cobra.RangeArgs(1, 2)),
	RunE:                  runConfigLegacy,
	DisableFlagsInUseLine: true,
	SilenceUsage:          true,
	SilenceErrors:         true,
}

var configGetCmd = &cobra.Command{
	Use:                   "get [<options>] <key>",
	Short:                 "Print the value of a configuration key",
	Args:                  configArgs(cobra.ExactArgs(1)),
	RunE:                  func(_ *cobra.Command, args []string) error { return runConfigGet(&getOpts, args[0]) },
	DisableFlagsInUseLine: true,
	SilenceUsage:          true,
	SilenceErrors:         true,
}

var configSetCmd = &cobra.Command{
	Use:   "set [<options>] <key> <value>",
	Short: "Set the value of a configuration key",
	Args:  configArgs(cobra.ExactArgs(2)),
	RunE: func(_ *cobra.Command, args []string) error {
		return runConfigWrite(&setOpts, args[0], args[1], writeSet)
	},
	DisableFlagsInUseLine: true,
	SilenceUsage:          true,
	SilenceErrors:         true,
}

var configUnsetCmd = &cobra.Command{
	Use:   "unset [<options>] <key>",
	Short: "Remove a configuration key",
	Args:  configArgs(cobra.ExactArgs(1)),
	RunE: func(_ *cobra.Command, args []string) error {
		return runConfigWrite(&unsetOpts, args[0], "", writeUnset)
	},
	DisableFlagsInUseLine: true,
	SilenceUsage:          true,
	SilenceErrors:         true,
}

// runConfigLegacy dispatches the pre-subcommand spellings of git config.
func runConfigLegacy(_ *cobra.Command, args []string) error {
	switch {
	case legacyGet, legacyGetAll:
		if len(args) != 1 {
			return usageError("--get takes exactly one key")
		}

		legacyOpts.all = legacyGetAll

		return runConfigGet(&legacyOpts, args[0])

	case legacyAdd:
		if len(args) != 2 {
			return usageError("--add takes a key and a value")
		}

		return runConfigWrite(&legacyOpts, args[0], args[1], writeAdd)

	case legacyReplaceAll:
		if len(args) != 2 {
			return usageError("--replace-all takes a key and a value")
		}

		legacyOpts.all = true

		return runConfigWrite(&legacyOpts, args[0], args[1], writeSet)

	case legacyUnset, legacyUnsetAll:
		if len(args) != 1 {
			return usageError("--unset takes exactly one key")
		}

		legacyOpts.all = legacyUnsetAll

		return runConfigWrite(&legacyOpts, args[0], "", writeUnset)

	case len(args) == 2:
		return runConfigWrite(&legacyOpts, args[0], args[1], writeSet)

	default:
		return runConfigGet(&legacyOpts, args[0])
	}
}

func runConfigGet(o *configOpts, rawKey string) error {
	key, err := parseConfigKey(rawKey)
	if err != nil {
		return err
	}

	sources, err := readSources(o)
	if err != nil {
		return err
	}

	values, err := effectiveConfigValues(sources, key)
	if err != nil {
		return err
	}

	if len(values) == 0 {
		// git prints nothing and exits 1 for a key that is not set. This is
		// distinct from a key whose value is the empty string, which still
		// prints one empty line and exits 0.
		return &gitExitError{code: exitNotFound}
	}

	if !o.all {
		values = values[len(values)-1:]
	}

	for _, v := range values {
		if o.path {
			if v, err = expandPath(v); err != nil {
				return err
			}
		}

		fmt.Println(v)
	}

	return nil
}

type writeMode int

const (
	writeSet writeMode = iota
	writeAdd
	writeUnset
)

func runConfigWrite(o *configOpts, rawKey, value string, mode writeMode) error {
	key, err := parseConfigKey(rawKey)
	if err != nil {
		return err
	}

	target, err := writeTarget(o)
	if err != nil {
		return err
	}

	err = gitconfig.UpdateFile(target.path, func(f *gitconfig.File) error {
		switch mode {
		case writeAdd:
			return f.Add(key, value)

		case writeUnset:
			if !o.all && len(f.Values(key)) > 1 {
				fmt.Fprintf(os.Stderr, "warning: %s has multiple values\n", rawKey)

				return &gitExitError{
					code: exitCannotReplace,
					msg:  fmt.Sprintf("error: cannot unset multiple values for %s; use --all", rawKey),
				}
			}

			n, err := f.UnsetAll(key)
			if err == nil && n == 0 {
				return &gitExitError{code: exitUnsetMissing}
			}

			return err

		case writeSet:
			if o.all {
				return f.ReplaceAll(key, value)
			}

			err := f.Set(key, value)
			if !errors.Is(err, gitconfig.ErrMultipleValues) {
				return err
			}

			fmt.Fprintf(os.Stderr, "warning: %s has multiple values\n", rawKey)

			return &gitExitError{
				code: exitCannotReplace,
				msg: fmt.Sprintf("error: cannot overwrite multiple values with a single value\n"+
					"       Use --add or --all to change %s.", rawKey),
			}
		}

		return nil
	})
	if err != nil {
		return configReadError(target, err)
	}

	return nil
}

// parseConfigKey converts Git's key diagnostics into exit-1 errors.
func parseConfigKey(raw string) (gitconfig.Key, error) {
	key, err := gitconfig.ParseKey(raw)
	if err != nil {
		return gitconfig.Key{}, &gitExitError{code: exitInvalidKey, msg: "error: " + err.Error()}
	}

	return key, nil
}

func configReadError(cf configFile, err error) error {
	var perr *gitconfig.ParseError
	if errors.As(err, &perr) {
		return &gitExitError{
			code: exitFatal,
			msg:  fmt.Sprintf("fatal: bad config line %d in file %s", perr.Line, cf.display),
		}
	}

	return err
}

func usageError(msg string) error {
	return &gitExitError{code: exitUsage, msg: "error: " + msg}
}

func configArgs(validate cobra.PositionalArgs) cobra.PositionalArgs {
	return func(cmd *cobra.Command, args []string) error {
		if err := validate(cmd, args); err != nil {
			return usageError(err.Error())
		}

		if err := cmd.ValidateFlagGroups(); err != nil {
			return usageError(err.Error())
		}

		return nil
	}
}

// expandPath applies --path canonicalization: a leading ~ becomes the user's
// home directory. Any other value is returned unchanged.
func expandPath(v string) (string, error) {
	if !strings.HasPrefix(v, "~") {
		return v, nil
	}

	if v == "~" || strings.HasPrefix(v, "~/") {
		home, err := os.UserHomeDir()
		if err != nil {
			return "", err
		}

		if v == "~" {
			return home, nil
		}

		return filepath.Join(home, v[2:]), nil
	}

	name, suffix, _ := strings.Cut(v[1:], "/")

	account, err := user.Lookup(name)
	if err == nil && account.HomeDir != "" {
		if suffix == "" {
			return account.HomeDir, nil
		}

		return filepath.Join(account.HomeDir, suffix), nil
	}

	return "", &gitExitError{
		code: exitFatal,
		msg:  fmt.Sprintf("fatal: failed to expand user dir in: '%s'", v),
	}
}
package main

import (
	"errors"
	"fmt"
	"io"
	"os"
	"os/exec"
	"path/filepath"
	"runtime"
	"slices"
	"strconv"
	"strings"

	gitconfig "github.com/go-git/cli/internal/plumbing/format/config"
)

const defaultSystemConfigFile = "/etc/gitconfig"

// gitExitError carries a git-compatible exit status out of a command. msg, when
// non-empty, is the single stderr line to print; main must not print the
// error itself, because git stays silent for some non-zero statuses (a
// missing key exits 1, an unset of a missing key exits 5, both without
// diagnostics).
type gitExitError struct {
	code int
	msg  string
}

func (e *gitExitError) Error() string {
	if e.msg != "" {
		return e.msg
	}

	return fmt.Sprintf("exit status %d", e.code)
}

// configFile names a configuration file twice: the path used for all I/O, and
// the spelling git would use for it in a diagnostic. They differ for a
// repository discovered from the working tree, which git reports relative to
// the top level.
type configFile struct {
	path    string
	display string
}

// configSource is one configuration file consulted for a read, or the set of
// -c command-line overrides.
type configSource struct {
	location configFile
	file     *gitconfig.File

	overrides []configOverride
	includes  bool
}

// readSources returns the files to consult, lowest precedence first.
//
// A location flag limits the sources to one scope. Otherwise git's default
// precedence applies.
func readSources(o *configOpts) ([]configSource, error) {
	if err := validateNoSystem(); err != nil {
		return nil, err
	}

	if files, ok, err := explicitReadFiles(o); err != nil {
		return nil, configRepositoryError(err)
	} else if ok {
		sources := make([]configSource, 0, len(files))
		for _, file := range files {
			src, err := loadSource(file)
			if err != nil {
				return nil, err
			}

			sources = append(sources, src)
		}

		return sources, nil
	}

	sources := make([]configSource, 0)

	if p, ok, err := systemConfigPath(); err != nil {
		return nil, err
	} else if ok {
		src, loaded, err := loadOptionalSource(absoluteFile(p))
		if err != nil {
			return nil, err
		}

		if loaded {
			src.includes = true
			sources = append(sources, src)
		}
	}

	for _, p := range globalConfigPaths() {
		src, loaded, err := loadOptionalSource(absoluteFile(p))
		if err != nil {
			return nil, err
		}

		if loaded {
			src.includes = true
			sources = append(sources, src)
		}
	}

	sources, err := appendLocalConfigSources(sources)
	if err != nil {
		return nil, err
	}

	if len(configOverrideList) > 0 {
		cwd, err := os.Getwd()
		if err != nil {
			return nil, err
		}

		sources = append(sources, configSource{
			location:  configFile{path: filepath.Join(cwd, ".gitconfig-command-line")},
			overrides: configOverrideList,
			includes:  true,
		})
	}

	return sources, nil
}

func appendLocalConfigSources(sources []configSource) ([]configSource, error) {
	// Being outside a repository is not an error for a default read: -c
	// overrides and the global files still apply, as they do in git.
	file, err := localConfigFile()
	if errors.Is(err, errNoRepository) {
		return sources, nil
	}

	if err != nil {
		return nil, configRepositoryError(err)
	}

	source, err := loadSource(file)
	if err != nil {
		return nil, err
	}

	source.includes = true
	sources = append(sources, source)

	worktree, enabled, err := worktreeConfigFile(source.file)
	if err != nil || !enabled {
		return sources, err
	}

	worktreeSource, err := loadSource(worktree)
	if err != nil {
		return nil, err
	}

	worktreeSource.includes = true

	return append(sources, worktreeSource), nil
}

// absoluteFile names a file that git reports by its full path, which is how
// it reports every file it did not discover by walking up from the cwd.
func absoluteFile(path string) configFile {
	return configFile{path: path, display: path}
}

// writeTarget returns the single file a mutation applies to. Writes default
// to the repository config, never to the merged view.
func writeTarget(o *configOpts) (configFile, error) {
	if err := validateNoSystem(); err != nil {
		return configFile{}, err
	}

	if file, ok, err := explicitWriteLocation(o); err != nil {
		return configFile{}, configRepositoryError(err)
	} else if ok {
		return file, nil
	}

	file, err := localConfigFile()

	return file, configRepositoryError(err)
}

func configRepositoryError(err error) error {
	if err == nil {
		return nil
	}

	var exitErr *gitExitError
	if errors.As(err, &exitErr) {
		return err
	}

	return &gitExitError{code: exitFatal, msg: "fatal: " + err.Error()}
}

func explicitReadFiles(o *configOpts) ([]configFile, bool, error) {
	switch {
	case o.file != "":
		if o.file == "-" {
			return []configFile{{path: "-", display: "standard input"}}, true, nil
		}

		return []configFile{absoluteFile(o.file)}, true, nil

	case o.local:
		f, err := localConfigFile()

		return []configFile{f}, true, err

	case o.global:
		paths := globalConfigPaths()

		files := make([]configFile, 0, len(paths))
		for _, path := range paths {
			files = append(files, absoluteFile(path))
		}

		return files, true, nil

	case o.system:
		p, ok, err := systemConfigPath()
		if err != nil {
			return nil, true, err
		}

		if !ok {
			return nil, true, errors.New("system config is disabled by GIT_CONFIG_NOSYSTEM")
		}

		return []configFile{absoluteFile(p)}, true, nil
	}

	return nil, false, nil
}

// explicitWriteLocation resolves the single file changed by an explicit scope.
func explicitWriteLocation(o *configOpts) (configFile, bool, error) {
	switch {
	case o.file != "":
		if o.file == "-" {
			return configFile{}, true, &gitExitError{
				code: exitFatal,
				msg:  "fatal: writing to stdin is not supported",
			}
		}

		return absoluteFile(o.file), true, nil

	case o.local:
		f, err := localConfigFile()

		return f, true, err

	case o.global:
		paths := globalConfigPaths()
		for _, path := range slices.Backward(paths) {
			if _, err := os.Stat(path); err == nil {
				return absoluteFile(path), true, nil
			}
		}

		if len(paths) == 0 {
			return configFile{}, true, errors.New("no global config file available")
		}

		return absoluteFile(paths[len(paths)-1]), true, nil

	case o.system:
		p, ok, err := systemConfigPath()
		if err != nil {
			return configFile{}, true, err
		}

		if !ok {
			return configFile{}, true, errors.New("system config is disabled by GIT_CONFIG_NOSYSTEM")
		}

		return absoluteFile(p), true, nil
	}

	return configFile{}, false, nil
}

func loadSource(cf configFile) (configSource, error) {
	if cf.path == "-" {
		data, err := io.ReadAll(os.Stdin)
		if err != nil {
			return configSource{}, err
		}

		f, err := gitconfig.Parse(data)
		if err != nil {
			return configSource{}, configReadError(cf, err)
		}

		return configSource{location: cf, file: f}, nil
	}

	f, err := gitconfig.ReadFile(cf.path)
	if err != nil {
		return configSource{}, configReadError(cf, err)
	}

	return configSource{location: cf, file: f}, nil
}

// loadOptionalSource ignores missing and unreadable system/global files, as
// git does, but still reports malformed files instead of hiding corruption.
func loadOptionalSource(cf configFile) (configSource, bool, error) {
	f, err := gitconfig.ReadFile(cf.path)
	if err != nil {
		var perr *gitconfig.ParseError
		if errors.As(err, &perr) {
			return configSource{}, false, configReadError(cf, err)
		}

		return configSource{}, false, nil
	}

	return configSource{location: cf, file: f}, true, nil
}

// globalConfigPaths returns the per-user config files in ascending precedence
// order, so ~/.gitconfig wins over the XDG file as it does in git.
func globalConfigPaths() []string {
	if p, ok := os.LookupEnv("GIT_CONFIG_GLOBAL"); ok {
		if p == "" || p == os.DevNull {
			return nil
		}

		return []string{p}
	}

	var paths []string

	if xdg := os.Getenv("XDG_CONFIG_HOME"); xdg != "" {
		paths = append(paths, filepath.Join(xdg, "git", "config"))
	} else if home, err := os.UserHomeDir(); err == nil {
		paths = append(paths, filepath.Join(home, ".config", "git", "config"))
	}

	if home, err := os.UserHomeDir(); err == nil {
		paths = append(paths, filepath.Join(home, ".gitconfig"))
	}

	return paths
}

// systemConfigPath reports the system config file, and whether the system
// scope is enabled at all.
func systemConfigPath() (string, bool, error) {
	noSystem, err := noSystemConfig()
	if err != nil {
		return "", false, err
	}

	if noSystem {
		return "", false, nil
	}

	if p, ok := os.LookupEnv("GIT_CONFIG_SYSTEM"); ok {
		if p == "" || p == os.DevNull {
			return "", false, nil
		}

		return p, true, nil
	}

	return defaultSystemConfigPath(), true, nil
}

func validateNoSystem() error {
	_, err := noSystemConfig()

	return err
}

func noSystemConfig() (bool, error) {
	value := os.Getenv("GIT_CONFIG_NOSYSTEM")
	noSystem, valid := gitBool(value, false)

	if !valid {
		return false, &gitExitError{
			code: exitFatal,
			msg: fmt.Sprintf(
				"fatal: bad boolean environment value '%s' for 'GIT_CONFIG_NOSYSTEM'",
				value,
			),
		}
	}

	return noSystem, nil
}

func defaultSystemConfigPath() string {
	gitPath, err := exec.LookPath("git")
	if err == nil && !sameExecutable(gitPath) {
		if path := systemConfigPathForExecutable(runtime.GOOS, gitPath); path != "" {
			return path
		}
	}

	if runtime.GOOS == "windows" {
		if programFiles := os.Getenv("PROGRAMFILES"); programFiles != "" {
			return filepath.Join(programFiles, "Git", "etc", "gitconfig")
		}
	}

	return defaultSystemConfigFile
}

func sameExecutable(path string) bool {
	executable, err := os.Executable()
	if err != nil {
		return false
	}

	want, err := os.Stat(executable)
	if err != nil {
		return false
	}

	got, err := os.Stat(path)

	return err == nil && os.SameFile(want, got)
}

func systemConfigPathForExecutable(goos, executable string) string {
	dir := filepath.Dir(executable)

	var prefix string

	switch filepath.Base(dir) {
	case "bin", "cmd":
		prefix = filepath.Dir(dir)
	case "git-core":
		prefix = filepath.Dir(filepath.Dir(dir))
	default:
		return ""
	}

	if goos != "windows" && prefix == "/usr" {
		return defaultSystemConfigFile
	}

	return filepath.Join(prefix, "etc", "gitconfig")
}

// localConfigFile returns the repository's config file. For a linked worktree
// this is the common directory's config, not the worktree's own git dir.
func localConfigFile() (configFile, error) {
	gitDir, display, err := discoverGitDir()
	if err != nil {
		return configFile{}, err
	}

	common := commonGitDir(gitDir)
	if common != gitDir {
		// Resolving through commondir yields an absolute path, and that is
		// what git reports for a linked worktree.
		display = common
	}

	return configFile{
		path: filepath.Join(common, "config"),
		// Concatenated rather than joined: git names a bare repository's
		// config "./config", which filepath.Join would clean to "config".
		display: display + "/config",
	}, nil
}

func worktreeConfigFile(local *gitconfig.File) (configFile, bool, error) {
	key := gitconfig.Key{Section: "extensions", Name: "worktreeConfig"}

	var (
		value           string
		implicit, found bool
	)

	for _, entry := range local.Entries() {
		if entry.Key.Matches(key) {
			value, implicit, found = entry.Value, entry.Implicit, true
		}
	}

	enabled := false

	if found {
		var valid bool

		enabled, valid = gitBool(value, implicit)
		if !valid {
			return configFile{}, false, &gitExitError{
				code: exitFatal,
				msg: fmt.Sprintf(
					"fatal: bad boolean config value '%s' for 'extensions.worktreeconfig'",
					value,
				),
			}
		}
	}

	if !enabled {
		return configFile{}, false, nil
	}

	gitDir, display, err := discoverGitDir()
	if err != nil {
		return configFile{}, false, err
	}

	return configFile{
		path:    filepath.Join(gitDir, "config.worktree"),
		display: display + "/config.worktree",
	}, true, nil
}

func gitBool(value string, implicit bool) (bool, bool) {
	if implicit {
		return true, true
	}

	switch strings.ToLower(value) {
	case "true", "yes", "on", "1":
		return true, true
	case "", "false", "no", "off", "0":
		return false, true
	}

	n, err := strconv.ParseInt(value, 10, 64)

	return n != 0, err == nil
}

// commonGitDir follows a linked worktree's `commondir` pointer back to the
// main git directory, which is where shared state such as config lives.
func commonGitDir(gitDir string) string {
	data, err := os.ReadFile(filepath.Join(gitDir, "commondir"))
	if err != nil {
		return gitDir
	}

	common := strings.TrimSpace(string(data))
	if common == "" {
		return gitDir
	}

	if !filepath.IsAbs(common) {
		common = filepath.Join(gitDir, common)
	}

	return filepath.Clean(common)
}

