	}

	var out []edit

	processed := map[int]bool{}

	for idx := range touched {
		if processed[idx] {
			continue
		}

		var group []int

		for candidate, s := range f.sections {
			if s.key.sameSection(f.sections[idx].key) {
				group = append(group, candidate)
