	slices.SortFunc(edits, func(a, b edit) int { return b.start - a.start })

	data := f.data
	for _, e := range edits {
		out := make([]byte, 0, len(data)-(e.end-e.start)+len(e.text))
		out = append(out, data[:e.start]...)
		out = append(out, e.text...)
