}
package main

import (
	"errors"
	"fmt"
	"os"
	"path/filepath"
	"strings"
)

// gitDirName is the name of a repository's git directory inside a work tree.
const gitDirName = ".git"

var errNoRepository = errors.New("not a git repository")

// findGitDir locates the repository's git directory.
func findGitDir() (string, error) {
	path, _, err := discoverGitDir()

	return path, err
}

// discoverGitDir locates the repository's git directory and returns both the
// path to use for I/O and the spelling git would use to name it in a
// diagnostic.
//
// It handles the three shapes git supports: a .git directory in the working
// tree or an ancestor, a .git *file* pointing at a linked worktree's git dir,
// and a bare repository whose working directory is the git dir itself.
//
// The two results differ because git chdirs to the top level of the working
// tree before doing anything, which leaves its GIT_DIR relative; gogit does
// not chdir, so it needs the absolute path to open the file and the relative
// one to report it.
func discoverGitDir() (string, string, error) {
	if d := os.Getenv("GIT_DIR"); d != "" {
		// An explicit GIT_DIR is reported exactly as it was given.
		return d, d, nil
	}

	dir, err := os.Getwd()
	if err != nil {
		return "", "", err
	}

	for {
		gitPath := filepath.Join(dir, gitDirName)

		info, err := os.Stat(gitPath)
		switch {
		case err == nil && info.IsDir():
			return gitPath, gitDirName, nil
		case err == nil && info.Mode().IsRegular():
			// A linked worktree resolves to an absolute path, and git reports
			// it that way.
			resolved, err := readGitFile(gitPath)

			return resolved, resolved, err
		}

		if isGitDir(dir) {
			// A bare repository is its own git dir, which git names ".".
			return dir, ".", nil
		}

		parent := filepath.Dir(dir)
		if parent == dir {
			return "", "", errNoRepository
		}

		dir = parent
	}
}

// readGitFile resolves a ".git" file, whose contents are "gitdir: <path>".
func readGitFile(path string) (string, error) {
	data, err := os.ReadFile(path)
	if err != nil {
		return "", err
	}

	target, ok := strings.CutPrefix(strings.TrimSpace(string(data)), "gitdir:")
	if !ok {
		return "", fmt.Errorf("invalid gitfile format: %s", path)
	}

	target = strings.TrimSpace(target)
	if target == "" {
		return "", fmt.Errorf("invalid gitfile format: %s", path)
	}

	if !filepath.IsAbs(target) {
		target = filepath.Join(filepath.Dir(path), target)
	}

	target = filepath.Clean(target)
	if !isGitDir(target) && !isLinkedWorktreeGitDir(target) {
		return "", fmt.Errorf("not a git repository: %s", target)
	}

	return target, nil
}

func isLinkedWorktreeGitDir(dir string) bool {
	data, err := os.ReadFile(filepath.Join(dir, "commondir"))
	if err != nil {
		return false
	}

	common := strings.TrimSpace(string(data))
	if common == "" {
		return false
	}

	if !filepath.IsAbs(common) {
		common = filepath.Join(dir, common)
	}

	return isGitDir(filepath.Clean(common))
}

// isGitDir reports whether dir is itself a git directory, which is how a bare
// repository presents itself.
func isGitDir(dir string) bool {
	if _, err := os.Stat(filepath.Join(dir, "HEAD")); err != nil {
		return false
	}

	return isDir(filepath.Join(dir, "objects")) && isDir(filepath.Join(dir, "refs"))
}

func isDir(path string) bool {
	info, err := os.Stat(path)

	return err == nil && info.IsDir()
}
package main

import (
	"fmt"
	"strings"
	"sync"

	gitconfig "github.com/go-git/cli/internal/plumbing/format/config"
	"github.com/go-git/go-git/v6/config"
)

var (
	configOverridesRaw []string
	configOverrides    = map[string]string{}
	configImplicit     = map[string]bool{}
	configOverrideMu   sync.Mutex

	// configOverrideList keeps the -c overrides in the order they were given
	// and with their keys normalised, which the config command needs to
	// report repeated values and to match subsection spellings. The map above
	// stays keyed by the raw string for the existing callers.
	configOverrideList []configOverride
)

// configOverride is a single -c key=value pair with its key parsed.
type configOverride struct {
	key      gitconfig.Key
	value    string
	implicit bool
}

// splitKV splits "<key>=<value>" into (key, value, true). Invalid input
// (no '=' or empty key) returns ("", "", false). Empty value is allowed.
func splitKV(s string) (string, string, bool) {
	idx := strings.IndexByte(s, '=')
	if idx <= 0 {
		return "", "", false
	}

	return s[:idx], s[idx+1:], true
}

func applyConfigOverride(key, value string) {
	applyConfigOverrideValue(key, value, false)
}

func applyConfigOverrideValue(key, value string, implicit bool) {
	configOverrideMu.Lock()
	defer configOverrideMu.Unlock()

	configOverrides[key] = value
	configImplicit[key] = implicit
}

func resetConfigOverrides() {
	configOverrideMu.Lock()
	defer configOverrideMu.Unlock()

	configOverrides = map[string]string{}
	configImplicit = map[string]bool{}
	configOverridesRaw = nil
	configOverrideList = nil
}

// applyConfigOverridesFromFlags parses raw `-c k=v` values previously captured
// by cobra and populates the override map.
func applyConfigOverridesFromFlags() error {
	for _, raw := range configOverridesRaw {
		k, v, ok := splitKV(raw)
		implicit := !ok

		if !ok {
			k = raw
			v = ""

			if k == "" {
				return fmt.Errorf("invalid -c value %q", raw)
			}
		}

		key, kerr := gitconfig.ParseKey(k)
		if kerr != nil {
			return fmt.Errorf("invalid -c value %q: %w", raw, kerr)
		}

		configOverrideList = append(configOverrideList, configOverride{
			key: key, value: v, implicit: implicit,
		})

		applyConfigOverrideValue(k, v, implicit)
	}

	return nil
}

// hasConfigOverride reports whether key has been explicitly set via -c.
func hasConfigOverride(key string) bool {
	configOverrideMu.Lock()
	_, ok := configOverrides[key]
	configOverrideMu.Unlock()

	return ok
}

// configBool returns the effective boolean value for the given config key.
// Lookup order: -c override > defaultVal. Empty-string override means false.
// repoCfg is accepted for future expansion but not consulted in v1.
//
//nolint:unparam // repoCfg is part of the shared config helper contract.
func configBool(key string, repoCfg *config.Config, defaultVal bool) bool {
	configOverrideMu.Lock()
	v, ok := configOverrides[key]
	implicit := configImplicit[key]
	configOverrideMu.Unlock()

	_ = repoCfg

	if ok {
		if implicit {
			return true
		}

		return strings.EqualFold(v, "true")
	}

	return defaultVal
}

